package com.jobproof.modules.aibilling.infra;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="ai_billing_record") public class AiBillingRecordEntity {
 @Id private String id; @Column(name="usage_id") private String usageId; @Column(name="account_id") private String accountId; private String status; private String currency; @Column(name="estimated_amount") private BigDecimal estimatedAmount; @Column(name="actual_amount") private BigDecimal actualAmount; @Column(name="refunded_amount") private BigDecimal refundedAmount; @Column(name="pricing_snapshot") private String pricingSnapshot; @Column(name="channel_rate_snapshot") private BigDecimal channelRateSnapshot; @Column(name="settled_at") private Instant settledAt; @Version @Column(name="version_no") private int versionNo; @Column(name="created_at") private Instant createdAt;
 protected AiBillingRecordEntity(){} public String getId(){return id;} public String getUsageId(){return usageId;} public String getStatus(){return status;} public String getCurrency(){return currency;} public BigDecimal getEstimatedAmount(){return estimatedAmount;} public BigDecimal getActualAmount(){return actualAmount;} public BigDecimal getRefundedAmount(){return refundedAmount;} public String getPricingSnapshot(){return pricingSnapshot;} public BigDecimal getChannelRateSnapshot(){return channelRateSnapshot;} public Instant getSettledAt(){return settledAt;} public int getVersionNo(){return versionNo;}
}
